const crypto = require('node:crypto')
const fs = require('node:fs')
const path = require('node:path')

function runtimeDirectory (userDir) {
  const directory = fs.realpathSync(userDir)
  if (!fs.statSync(directory).isDirectory()) throw new Error('Node-RED user directory must be a directory')
  return directory
}

function regularFile (file) {
  return fs.existsSync(file) && fs.lstatSync(file).isFile()
}

function flowLocation (directory) {
  if (directory.includes(`${path.sep}local-validation${path.sep}`)) {
    const flowFile = path.join(directory, 'flows.json')
    if (!regularFile(flowFile)) throw new Error('Local-validation Flow file is missing')
    return { flowFile, credentialFile: path.join(directory, 'flows_cred.json'),
      backupRoot: path.join(directory, 'managed-bridge-backups') }
  }

  const configFile = path.join(directory, '.config.projects.json')
  if (!regularFile(configFile)) {
    throw new Error('Managed bridge editor requires a local-validation directory or an active Node-RED project')
  }
  const config = JSON.parse(fs.readFileSync(configFile, 'utf8'))
  const name = config.activeProject
  if (typeof name !== 'string' || !/^[A-Za-z0-9][A-Za-z0-9._-]*$/.test(name) ||
    !Object.hasOwn(config.projects || {}, name)) {
    throw new Error('Active Node-RED project is missing or invalid')
  }
  const projectsRoot = fs.realpathSync(path.join(directory, 'projects'))
  if (path.dirname(projectsRoot) !== directory) throw new Error('Projects directory escapes the user directory')
  const projectPath = path.join(projectsRoot, name)
  if (!fs.lstatSync(projectPath).isDirectory()) throw new Error('Active project must be a directory')
  const projectDir = fs.realpathSync(projectPath)
  if (path.dirname(projectDir) !== projectsRoot) throw new Error('Active project escapes the projects directory')
  const packageFile = path.join(projectDir, 'package.json')
  if (!regularFile(packageFile)) throw new Error('Active project package.json is missing')
  const settings = JSON.parse(fs.readFileSync(packageFile, 'utf8'))['node-red']?.settings
  const validName = name => typeof name === 'string' &&
    /^[A-Za-z0-9][A-Za-z0-9._-]*\.json$/.test(name) && path.basename(name) === name
  if (!validName(settings?.flowFile) || !validName(settings?.credentialsFile) ||
    settings.flowFile === settings.credentialsFile) {
    throw new Error('Active project must declare safe flowFile and credentialsFile names')
  }
  const flowFile = path.join(projectDir, settings.flowFile)
  const credentialFile = path.join(projectDir, settings.credentialsFile)
  if (!regularFile(flowFile)) throw new Error('Active project Flow file is missing or unsafe')
  if (fs.existsSync(credentialFile) && !regularFile(credentialFile)) {
    throw new Error('Active project credentials file must be a regular file')
  }
  return { flowFile, credentialFile,
    backupRoot: path.join(directory, 'managed-bridge-backups', name) }
}

function privateDirectory (directory) {
  if (fs.existsSync(directory)) {
    if (!fs.lstatSync(directory).isDirectory()) throw new Error('Bridge backup path must be a directory')
  } else {
    fs.mkdirSync(directory, { mode: 0o700 })
  }
}

function backupFlow (location, rev, flows) {
  const parent = path.dirname(location.backupRoot)
  if (parent !== path.dirname(location.flowFile)) privateDirectory(parent)
  privateDirectory(location.backupRoot)
  const backupDir = path.join(location.backupRoot,
    new Date().toISOString().replace(/[:.]/g, '-') + '-' + crypto.randomBytes(3).toString('hex'))
  fs.mkdirSync(backupDir, { mode: 0o700 })
  fs.writeFileSync(path.join(backupDir, 'api-flows.json'), JSON.stringify({ rev, flows }, null, 2),
    { flag: 'wx', mode: 0o600 })
  for (const file of [location.flowFile, location.credentialFile]) {
    if (!regularFile(file)) continue
    const target = path.join(backupDir, path.basename(file))
    fs.copyFileSync(file, target)
    fs.chmodSync(target, 0o600)
  }
  return backupDir
}

module.exports = { backupFlow, runtimeDirectory, flowLocation }
